# QVAC-owned Xcode links are generated by the build; --remove reverses them.
require 'xcodeproj'
app = ARGV.fetch(0)
project = Xcodeproj::Project.open(File.join(app, 'ios/Runner.xcodeproj'))
target = project.targets.find { |t| t.name == 'Runner' }
group = project.main_group.find_subpath('Qvac', false)
if group
  group.recursive_children.grep(Xcodeproj::Project::Object::PBXFileReference).each do |ref|
    target.build_phases.each { |phase| phase.files.select { |f| f.file_ref == ref }.each(&:remove_from_project) }
  end
  group.recursive_children.reverse_each(&:remove_from_project)
  group.remove_from_project
end
unless ARGV.include?('--remove')
  group = project.main_group.new_group('Qvac')
  source = group.new_file('Runner/Qvac/QvacWorklet.swift')
  target.source_build_phase.add_file_reference(source)
  bundle = group.new_file('Runner/Qvac/worker.bundle')
  target.resources_build_phase.add_file_reference(bundle)
  notices = group.new_file('Runner/Qvac/licenses')
  target.resources_build_phase.add_file_reference(notices)
  Dir.glob(File.join(app, 'ios/Frameworks/Qvac/*.xcframework')).sort.each do |file|
    ref = group.new_file('Frameworks/Qvac/' + File.basename(file))
    target.frameworks_build_phase.add_file_reference(ref)
    embed = target.copy_files_build_phases.find { |p| p.name == 'Embed Frameworks' }
    build = embed.add_file_reference(ref)
    build.settings = { 'ATTRIBUTES' => ['CodeSignOnCopy', 'RemoveHeadersOnCopy'] }
  end
end
project.save
